    <title>Terms Consent Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: #111827;
        --panel-border: #263244;
        --text: #e5e7eb;
        --muted: #9ca3af;
        --accent: #7c3aed;
        --accent-hover: #8b5cf6;
        --focus: rgba(124, 58, 237, 0.35);
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 24px;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(124, 58, 237, 0.18), transparent 35%),
          linear-gradient(180deg, #0a0f1d 0%, var(--bg) 100%);
        color: var(--text);
      }

      .card {
        width: min(100%, 460px);
        padding: 28px;
        border: 1px solid var(--panel-border);
        border-radius: 20px;
        background: rgba(17, 24, 39, 0.92);
        box-shadow: var(--shadow);
        backdrop-filter: blur(10px);
      }

      h1 {
        margin: 0 0 10px;
        font-size: 1.5rem;
        line-height: 1.2;
      }

      p {
        margin: 0 0 22px;
        color: var(--muted);
        line-height: 1.5;
      }

      .form-field {
        padding: 16px;
        border: 1px solid var(--panel-border);
        border-radius: 16px;
        background: rgba(255, 255, 255, 0.02);
      }

      .checkbox-row {
        display: flex;
        gap: 12px;
        align-items: flex-start;
      }

      input[type="checkbox"] {
        width: 18px;
        height: 18px;
        margin: 3px 0 0;
        accent-color: var(--accent);
      }

      label {
        display: block;
        font-weight: 600;
        cursor: pointer;
      }

      .helper-text {
        margin-top: 6px;
        color: var(--muted);
        font-size: 0.95rem;
        line-height: 1.45;
      }

      .actions {
        margin-top: 20px;
        display: flex;
        justify-content: flex-end;
      }

      button {
        border: 0;
        border-radius: 12px;
        padding: 12px 18px;
        background: linear-gradient(180deg, var(--accent-hover), var(--accent));
        color: white;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 10px 24px rgba(124, 58, 237, 0.28);
        transition: transform 0.15s ease, filter 0.15s ease;
      }

      button:hover {
        filter: brightness(1.05);
        transform: translateY(-1px);
      }

      button:focus-visible,
      input:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .status {
        min-height: 1.25rem;
        margin-top: 14px;
        color: #c4b5fd;
        font-size: 0.95rem;
      }
    </style>
  </head>
  <body>
    <main class="card">
      <h1>Terms of Use</h1>
      <p>Please review and confirm your consent before continuing.</p>

      <form id="consent-form" novalidate>
        <div class="form-field">
          <div class="checkbox-row">
            <input id="terms" name="terms" type="checkbox" required />
            <div>
              <label for="terms">I agree to the terms of use</label>
              <div class="helper-text">Required to submit this form.</div>
            </div>
          </div>
        </div>

        <div class="actions">
          <button type="submit">Submit</button>
        </div>

        <div class="status" id="status" aria-live="polite"></div>
      </form>
    </main>

    <script>
      const form = document.getElementById("consent-form");
      const status = document.getElementById("status");
      const terms = document.getElementById("terms");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!terms.checked) {
          terms.setCustomValidity("Please agree to the terms of use.");
          form.reportValidity();
          terms.setCustomValidity("");
          status.textContent = "";
          return;
        }

        status.textContent = "Consent submitted successfully.";
        form.reset();
      });
    </script>
  </body>
</html>
